import React,{useState,useEffect,useRef,createContext,useContext} from 'react';
import * as I from './icons';
import { Login } from './features/auth/Login.jsx';
import { Brand, IconButton, Field, Modal } from './components/ui.jsx';
import { useAuth } from './features/auth/useAuth.js';
import { loadUserDirectory, createUser } from './services/usersService.js';
import {ResponsiveContainer,BarChart,Bar,XAxis,YAxis,CartesianGrid,Tooltip,PieChart,Pie,Cell} from 'recharts';
import {TODAY,warehouses,categories,uid,money,num,date,stock,status,seed,applyMovement,checkout,receivePurchase,payInvoice,voidInvoice,cashExpected,csv,validQty} from './domain';
const Context=createContext();const useApp=()=>useContext(Context);
const STORAGE='ferro-demo-v1',palette=['#0c88f7','#0cafab','#7c43d2','#ff9a08','#18bb66','#ed4554','#586f8e'];
const navigation=[['inicio','Inicio',I.Home],['inventario','Inventario',I.Package],['movimientos','Movimientos de stock',I.ArrowsExchange],['compras','Compras',I.ShoppingCart],['ventas','Ventas y facturación',I.Receipt],['presupuestos','Presupuestos',I.FileText],['caja','Caja',I.Cash],['clientes','Clientes',I.Users],['proveedores','Proveedores',I.Truck],['reportes','Reportes',I.ChartBar],['usuarios','Usuarios y permisos',I.ShieldCheck],['configuracion','Configuración',I.Settings]];
const roleRoutes={Administrador:navigation.map(n=>n[0]),Vendedor:['inicio','inventario','ventas','presupuestos','caja','clientes'],Depósito:['inicio','inventario','movimientos','compras','proveedores']};
const cn=(...a)=>a.filter(Boolean).join(' ');

function Button({children,icon:Icon,variant='',className='',...props}){return <button className={cn('btn',variant,className)} {...props}>{Icon&&<Icon size={18}/>} {children}</button>}

function Badge({children}){return <span className={cn('badge',({'Disponible':'green','Pagada':'green','Recibida':'green','Ingreso':'green','Activa':'green','Stock bajo':'orange','Pendiente':'orange','Parcial':'blue','Sin stock':'red','Anulada':'red','Egreso':'red','Inactiva':'gray','Borrador':'purple'})[children]||'blue')}>{children}</span>}
function Empty({title='No hay resultados',text='Probá con otra búsqueda o cambiá los filtros.',action}){return <div className="empty"><I.Search size={32}/><h3>{title}</h3><p>{text}</p>{action}</div>}

function Search({value,onChange,placeholder='Buscar…'}){return <div className="search"><I.Search size={19}/><input aria-label={placeholder} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>{value&&<IconButton icon={I.X} label="Limpiar búsqueda" onClick={()=>onChange('')}/>}</div>}
function ProductImage({product,large=false}){const Icon=({Electricidad:I.Bolt,Plomería:I.Droplet,Tornillería:I.Tool,Construcción:I.Package,Seguridad:I.ShieldCheck})[product.category]||I.Box;return <span className={cn('product-image',large&&'large')}>{product.image?<img src={'/assets/'+product.image+'.png'} alt={product.name}/>:<Icon size={large?64:24}/>}</span>}
function ProductName({p}){return <span className="product-name"><ProductImage product={p}/><span><b>{p.name}</b><small>{p.brand} · {p.unit}</small></span></span>}
function PageTitle({title,subtitle,children}){return <div className="page-title"><div><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div><div className="page-actions">{children}</div></div>}
function Panel({title,icon:Icon,color='blue',action,children,className=''}){return <section className={cn('panel',className)}>{title&&<div className="panel-title"><h2>{Icon&&<span className={'title-icon '+color}><Icon size={19}/></span>}{title}</h2>{action}</div>}{children}</section>}
function Stat({label,value,note,icon:Icon,color='blue',onClick}){return <button className={'stat '+color} onClick={onClick} disabled={!onClick}><span className="stat-icon"><Icon size={28}/></span><div><span>{label}</span><strong>{value}</strong><small>{note}</small></div></button>}
function MiniStats({items}){return <div className="mini-stats">{items.map(([label,value,Icon,color])=><div key={label}><span className={'soft-icon '+(color||'blue')}><Icon size={23}/></span><div><small>{label}</small><strong>{value}</strong></div></div>)}</div>}
function Table({headers,children,empty=false}){return <div className="table-wrap"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{children}</tbody></table>{empty&&<Empty/>}</div>}

function FormModal({model,onClose}){const[values,setValues]=useState(model.values||{}),[error,setError]=useState(''),[busy,setBusy]=useState(false);return <Modal title={model.title} onClose={onClose} wide={model.fields.length>6}><form onSubmit={async e=>{e.preventDefault();setError('');setBusy(true);try{await model.onSave(values);onClose();}catch(err){setError(err.message);}finally{setBusy(false);}}}>{model.help&&<p className="form-help">{model.help}</p>}<div className={model.fields.length>4?'form-grid':'form-stack'}>{model.fields.filter(f=>!f.when||f.when(values)).map(f=><Field key={f.name} label={f.label}>{f.options?<select required={f.required!==false} value={values[f.name]??''} onChange={e=>setValues({...values,[f.name]:e.target.value})}>{f.placeholder&&<option value="">{f.placeholder}</option>}{f.options.map(x=><option key={typeof x==='object'?x.value:x} value={typeof x==='object'?x.value:x}>{typeof x==='object'?x.label:x}</option>)}</select>:<input required={f.required!==false} type={f.type||'text'} min={f.min} max={f.max} step={f.step||'any'} minLength={f.minLength} value={values[f.name]??''} onChange={e=>setValues({...values,[f.name]:e.target.value})}/>}</Field>)}</div>{error&&<div className="error" role="alert"><I.AlertTriangle size={18}/>{error}</div>}<div className="modal-actions"><Button variant="secondary" type="button" onClick={onClose}>Cancelar</Button><Button type="submit" icon={I.Check} disabled={busy}>{busy?'Guardando…':model.submit||'Guardar'}</Button></div></form></Modal>}

export function App(){const{user,loading,authError,completeLogin,logout}=useAuth();const[data,setData]=useState(()=>{try{return JSON.parse(localStorage.getItem(STORAGE))||seed();}catch{return seed();}}),[route,setRoute]=useState('inicio'),[warehouse,setWarehouse]=useState('Casa central'),[modal,setModal]=useState(null),[toast,setToast]=useState(null),[collapsed,setCollapsed]=useState(false),[topMenu,setTopMenu]=useState(''),[globalSearch,setGlobalSearch]=useState(''),[inventoryQuery,setInventoryQuery]=useState(''),[inventoryFilter,setInventoryFilter]=useState('Todos'),[cart,setCart]=useState([]),[saleClient,setSaleClient]=useState('c1'),[saleDiscount,setSaleDiscount]=useState(0);
useEffect(()=>{localStorage.setItem(STORAGE,JSON.stringify(data));},[data]);useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(null),4500);return()=>clearTimeout(t);}},[toast]);useEffect(()=>{if(!user){setModal(null);setCart([]);setRoute('inicio');setTopMenu('');}},[user]);
function notify(text,error=false){setToast({text,error});}function go(page){const allowed=roleRoutes[user.role]||['inicio'];if(!allowed.includes(page)&&!(page==='nueva-venta'&&allowed.includes('ventas'))){notify('Este módulo requiere otro perfil de acceso.',true);return;}setRoute(page);setTopMenu('');if(window.innerWidth<900)setCollapsed(true);window.scrollTo(0,0);}function commit(next,msg){next.audit=[{id:uid(),date:TODAY,user:user.name,action:msg},...(data.audit||[])].slice(0,100);setData(next);if(msg)notify(msg);}function act(fn,msg){try{commit(fn(data),msg);return true;}catch(e){notify(e.message,true);return false;}}function form(title,fields,values,onSave,help,submit){setModal({kind:'form',title,fields,values,onSave,help,submit});}function confirm(title,text,onConfirm){setModal({kind:'confirm',title,text,onConfirm});}
function productForm(p){if(user.role==='Vendedor'){notify('La edición de inventario requiere el perfil de depósito o administrador.',true);return;}const fields=[{name:'name',label:'Nombre del producto'},{name:'code',label:'Código / SKU'},{name:'barcode',label:'Código de barras',required:false},{name:'brand',label:'Marca'},{name:'category',label:'Categoría',options:categories},{name:'unit',label:'Unidad de venta',options:['unidad','caja','metro','kilo','bolsa','par']},{name:'cost',label:'Costo de compra (Gs.)',type:'number',min:0},{name:'price',label:'Precio de venta (Gs.)',type:'number',min:1},{name:'min',label:'Stock mínimo',type:'number',min:0}];if(!p)fields.push({name:'central',label:'Stock inicial · Casa central',type:'number',min:0},{name:'north',label:'Stock inicial · Depósito Norte',type:'number',min:0});form(p?'Editar producto':'Nuevo producto',fields,p||{category:'Herramientas',unit:'unidad',cost:0,price:0,min:5,central:0,north:0},v=>{const s=structuredClone(data);if(s.products.some(x=>x.id!==p?.id&&x.code.toLowerCase()===v.code.trim().toLowerCase()))throw Error('Ya existe un producto con ese código.');const item={...p,...v,id:p?.id||Math.max(...s.products.map(x=>x.id))+1,name:v.name.trim(),code:v.code.trim(),cost:Number(v.cost),price:Number(v.price),min:Number(v.min),stocks:p?.stocks||{'Casa central':Number(v.central),'Depósito Norte':Number(v.north)}};for(const q of Object.values(item.stocks))if(q>0)validQty(item,q);s.products=p?s.products.map(x=>x.id===p.id?item:x):[...s.products,item];commit(s,p?'Producto actualizado':'Producto creado');},'Los movimientos posteriores se registran desde Movimientos de stock.');}
function movementForm(p,type='Entrada'){if(user.role==='Vendedor'){notify('El registro de stock requiere el perfil de depósito o administrador.',true);return;}form('Registrar movimiento',[{name:'productId',label:'Producto',options:data.products.map(x=>({value:x.id,label:x.code+' · '+x.name})),placeholder:'Seleccionar producto'},{name:'type',label:'Tipo de movimiento',options:['Entrada','Salida','Ajuste','Transferencia']},{name:'warehouse',label:'Depósito de origen',options:warehouses},{name:'destination',label:'Depósito de destino',options:warehouses,when:v=>v.type==='Transferencia'},{name:'qty',label:'Cantidad',type:'number',min:0.01},{name:'reason',label:'Motivo / referencia'}],{productId:p?.id||'',type,warehouse,destination:warehouse===warehouses[0]?warehouses[1]:warehouses[0],qty:1,reason:''},v=>commit(applyMovement(data,v,user.name),'Movimiento registrado'),'Para reducir existencias, usá Salida. Ajuste registra una corrección positiva.');}
function contactForm(type,item){const clients=type==='clientes',key=clients?'clients':'suppliers';form(item?'Editar '+(clients?'cliente':'proveedor'):'Nuevo '+(clients?'cliente':'proveedor'),[{name:'name',label:'Nombre / razón social'},{name:'doc',label:'RUC / documento'},{name:'phone',label:'Teléfono',required:false},{name:'email',label:'Correo electrónico',type:'email',required:false},{name:'address',label:'Dirección',required:false},...(clients?[{name:'credit',label:'Límite de crédito (Gs.)',type:'number',min:0}]:[])],item||{credit:0},v=>{const s=structuredClone(data),c={...v,id:item?.id||uid(),credit:Number(v.credit)||0};s[key]=item?s[key].map(x=>x.id===item.id?c:x):[...s[key],c];commit(s,(clients?'Cliente':'Proveedor')+' guardado');});}
function viewInvoice(inv){setModal({kind:'invoice',id:inv.id});}function pay(inv){form('Registrar cobro',[{name:'amount',label:'Importe a cobrar (Gs.)',type:'number',min:1,max:inv.total-inv.paid},{name:'method',label:'Forma de pago',options:['Efectivo','Tarjeta','Transferencia']}],{amount:inv.total-inv.paid,method:'Efectivo'},v=>commit(payInvoice(data,inv.id,Number(v.amount),v.method),'Cobro registrado'),'Saldo pendiente: '+money(inv.total-inv.paid));}
function openSale(){setCart([]);setSaleDiscount(0);setSaleClient('c1');go('nueva-venta');}
const ctx={data,user,warehouse,go,commit,act,notify,form,confirm,modal,setModal,productForm,movementForm,contactForm,viewInvoice,pay,openSale,inventoryQuery,setInventoryQuery,inventoryFilter,setInventoryFilter,cart,setCart,saleClient,setSaleClient,saleDiscount,setSaleDiscount,setWarehouse};
if(loading)return <div className="loading"><I.Box size={40}/><p>Preparando tu espacio de trabajo…</p></div>;if(!user)return <Login initialError={authError} onLogin={u=>{completeLogin(u);setRoute('inicio');}}/>;
const allowed=roleRoutes[user.role]||['inicio'],current=navigation.find(n=>n[0]===route)?.[1]||(route==='nueva-venta'?'Nueva venta':'Inicio');
return <Context.Provider value={ctx}><div className={cn('shell',collapsed&&'collapsed')}><aside className="sidebar"><Brand/><div className="nav-caption">ESPACIO DE TRABAJO</div><nav>{navigation.filter(n=>allowed.includes(n[0])).map(([id,label,Icon])=><button key={id} aria-label={label} className={cn((route===id||(id==='ventas'&&route==='nueva-venta'))&&'selected')} onClick={()=>go(id)} title={collapsed?label:undefined}><Icon size={21}/><span>{label}</span>{id==='inventario'&&<small>{data.products.length}</small>}</button>)}</nav><div className="sidebar-bottom"><span className="demo-dot"/><div><b>Modo demostración</b><small>Tus cambios se guardan aquí</small></div></div></aside><div className="main-shell"><header className="topbar"><IconButton icon={I.Menu} label="Mostrar u ocultar menú" onClick={()=>setCollapsed(!collapsed)}/><span className="breadcrumb">Mi negocio <I.ChevronRight size={13}/> <b>{current}</b></span><form className="global-search" onSubmit={e=>{e.preventDefault();setInventoryQuery(globalSearch);go('inventario');}}><I.Search size={17}/><input aria-label="Buscar en el inventario" placeholder="Buscar producto o código…" value={globalSearch} onChange={e=>setGlobalSearch(e.target.value)}/><kbd>↵</kbd></form><label className="warehouse"><I.BuildingStore size={18}/><select aria-label="Depósito activo" value={warehouse} onChange={e=>setWarehouse(e.target.value)}>{warehouses.map(w=><option key={w}>{w}</option>)}</select></label><div className="top-pop"><button className="notification icon-btn" aria-label="Notificaciones de stock" onClick={()=>setTopMenu(topMenu==='alerts'?'':'alerts')}><I.Bell size={22}/>{data.products.some(p=>stock(p,warehouse)<=p.min)&&<span/>}</button>{topMenu==='alerts'&&<div className="dropdown"><b>Atención al inventario</b><p>{data.products.filter(p=>stock(p,warehouse)<=p.min).length} productos necesitan reposición en {warehouse}.</p><Button variant="text" onClick={()=>{setInventoryFilter('Stock bajo');go('inventario');}}>Revisar existencias <I.ArrowRight size={16}/></Button></div>}</div><div className="top-pop"><button className="profile" onClick={()=>setTopMenu(topMenu==='profile'?'':'profile')}><span className="avatar">{user.name[0]}</span><span><b>{user.name.split(' ')[0]}</b><small>{user.role}</small></span><I.ChevronDown size={14}/></button>{topMenu==='profile'&&<div className="dropdown"><b>{user.name}</b><p>{user.username}</p><Button variant="secondary" icon={I.Logout} onClick={logout}>Cerrar sesión</Button></div>}</div></header><main className="content">{route==='inicio'?<Dashboard/>:route==='inventario'?<Inventory/>:route==='movimientos'?<Movements/>:route==='ventas'?<Sales/>:route==='nueva-venta'?<SaleEditor/>:route==='compras'?<Purchases/>:route==='presupuestos'?<Quotes/>:route==='caja'?<Cash/>:route==='clientes'||route==='proveedores'?<Contacts key={route} type={route}/>:route==='reportes'?<Reports/>:route==='usuarios'?<Users/>:<Settings/>}</main><footer><span><b>NEXA</b> · {data.settings.company}</span><span>Datos de ejemplo <span className="footer-sep">|</span> 26 oct. 2026</span></footer></div>{toast&&<div role="status" className={cn('toast',toast.error&&'toast-error')}>{toast.error?<I.AlertTriangle size={20}/>:<I.CircleCheck size={20}/>}<span>{toast.text}</span><IconButton icon={I.X} label="Cerrar mensaje" onClick={()=>setToast(null)}/></div>}{modal?.kind==='form'&&<FormModal key={modal.title} model={modal} onClose={()=>setModal(null)}/>} {modal?.kind==='confirm'&&<Modal title={modal.title} onClose={()=>setModal(null)}><p className="confirm-text">{modal.text}</p><div className="modal-actions"><Button variant="secondary" onClick={()=>setModal(null)}>Cancelar</Button><Button onClick={()=>{try{modal.onConfirm();setModal(null);}catch(e){notify(e.message,true);}}}>Confirmar</Button></div></Modal>}{modal?.kind==='invoice'&&<InvoiceModal id={modal.id}/>} {modal?.kind==='purchase'&&<PurchaseModal/>}{modal?.kind==='purchase-detail'&&<PurchaseDetail id={modal.id}/>} {modal?.kind==='statement'&&<Statement id={modal.id}/>}</div></Context.Provider>;
}
function SalesChart({invoices}){const values=Array.from({length:7},(_,i)=>{const d='2026-10-'+(20+i);return {name:(20+i)+' oct.',value:invoices.filter(x=>x.date===d&&x.state!=='Anulada').reduce((a,x)=>a+x.total,0)};});return <div className="chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={values} margin={{left:0,right:10,top:15,bottom:0}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e9eef4"/><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#63748c'}}/><YAxis tickFormatter={v=>v>=1e6?(v/1e6)+' M':(v/1000)+' mil'} tickLine={false} axisLine={false} tick={{fontSize:10,fill:'#63748c'}} width={48}/><Tooltip formatter={v=>money(v)} cursor={{fill:'#f0f6fd'}}/><Bar isAnimationActive={false} dataKey="value" name="Ventas" fill="#0c88f7" radius={[3,3,0,0]} maxBarSize={62}/></BarChart></ResponsiveContainer></div>}
function Composition({products,warehouse}){const data=categories.map((name,i)=>({name,value:products.filter(p=>p.category===name).reduce((a,p)=>a+stock(p,warehouse)*p.cost,0),color:palette[i]})).filter(x=>x.value>0);return <div className="composition"><div className="donut"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie isAnimationActive={false} data={data} dataKey="value" innerRadius="63%" outerRadius="90%" paddingAngle={2} stroke="none">{data.map(x=><Cell key={x.name} fill={x.color}/>)}</Pie><Tooltip formatter={v=>money(v)}/></PieChart></ResponsiveContainer><span><b>{products.length}</b><small>productos</small></span></div><div className="legend">{data.slice(0,5).map(x=><div key={x.name}><span style={{background:x.color}}/><b>{x.name}</b><small>{Math.round(x.value/data.reduce((a,x)=>a+x.value,0)*100)}%</small></div>)}</div></div>}
function Dashboard(){const{data,warehouse,go,openSale,setInventoryFilter,movementForm,viewInvoice}=useApp();const invoices=data.invoices.filter(x=>x.state!=='Anulada'&&x.warehouse===warehouse),low=data.products.filter(p=>stock(p,warehouse)<=p.min),debt=invoices.filter(x=>x.total>x.paid),total=invoices.reduce((a,x)=>a+x.total,0);return <><PageTitle title="Resumen del negocio" subtitle="Hoy es lunes, 26 de octubre de 2026"><Button icon={I.Plus} variant="green" onClick={openSale}>Nueva venta</Button></PageTitle><div className="stats-grid"><Stat label="Ventas del mes" value={money(total)} note={invoices.length+' ventas registradas'} icon={I.ShoppingCart} color="green" onClick={()=>go('ventas')}/><Stat label="Productos" value={num(data.products.length)} note="Productos en tu catálogo" icon={I.Box} onClick={()=>go('inventario')}/><Stat label="Stock bajo" value={low.length} note="Productos por reponer" icon={I.AlertTriangle} color="orange" onClick={()=>{setInventoryFilter('Stock bajo');go('inventario');}}/><Stat label="Facturas pendientes" value={debt.length} note={money(debt.reduce((a,x)=>a+x.total-x.paid,0))} icon={I.Receipt} color="purple" onClick={()=>go('ventas')}/></div><div className="dashboard-main"><Panel title="Productos con stock bajo" icon={I.AlertTriangle} color="red" action={<Button variant="text" onClick={()=>{setInventoryFilter('Stock bajo');go('inventario');}}>Ver inventario <I.ArrowRight size={16}/></Button>}><Table headers={['Código / producto','Disponible','Mínimo','Estado','']} empty={!low.length}>{low.slice(0,6).map(p=><tr key={p.id}><td><ProductName p={p}/></td><td className="danger-text"><b>{num(stock(p,warehouse))}</b> <small>{p.unit}</small></td><td>{p.min}</td><td><Badge>{status(p,warehouse)}</Badge></td><td><Button variant="outline small" icon={I.Plus} onClick={()=>movementForm(p)}>Reponer</Button></td></tr>)}</Table></Panel><Panel title="Últimas ventas" icon={I.ChartBar} color="green" action={<Button variant="text" onClick={()=>go('ventas')}>Ver todas <I.ArrowRight size={16}/></Button>}><Table headers={['Comprobante','Cliente','Total','Estado']} empty={!invoices.length}>{invoices.slice(0,6).map(x=><tr key={x.id} onClick={()=>viewInvoice(x)} className="clickable"><td><button className="table-link" onClick={e=>{e.stopPropagation();viewInvoice(x);}}>{x.number.slice(-7)}</button><small className="block">{date(x.date)}</small></td><td>{data.clients.find(c=>c.id===x.client)?.name}</td><td className="nowrap"><b>{money(x.total)}</b></td><td><Badge>{x.state}</Badge></td></tr>)}</Table></Panel></div><div className="dashboard-bottom"><Panel title="Ventas de los últimos 7 días" icon={I.ChartBar} action={<span className="panel-total"><small>Total del período</small><b>{money(total)}</b></span>}><SalesChart invoices={invoices}/></Panel><Panel title="Composición del inventario" icon={I.ChartBar} color="purple"><Composition products={data.products} warehouse={warehouse}/></Panel></div></>}
function Inventory(){const{data,warehouse,productForm,movementForm,inventoryQuery:q,setInventoryQuery:setQ,inventoryFilter:filter,setInventoryFilter:setFilter,go}=useApp();const[category,setCategory]=useState('Todas'),[selected,setSelected]=useState(1),[page,setPage]=useState(1);const p=data.products.find(x=>x.id===selected)||data.products[0],filtered=data.products.filter(p=>(p.name+' '+p.code+' '+p.barcode+' '+p.brand).toLowerCase().includes(q.toLowerCase())&&(category==='Todas'||p.category===category)&&(filter==='Todos'||(filter==='Stock bajo'?stock(p,warehouse)<=p.min:status(p,warehouse)===filter)));useEffect(()=>setPage(1),[q,filter,category,warehouse]);const rows=filtered.slice((page-1)*7,page*7);return <><PageTitle title="Inventario" subtitle="Controlá tus productos y existencias."><Button variant="secondary" icon={I.Download} onClick={()=>csv('inventario.csv',['Código','Producto','Categoría','Unidad','Depósito','Stock','Mínimo','Costo','Precio'],filtered.map(p=>[p.code,p.name,p.category,p.unit,warehouse,stock(p,warehouse),p.min,p.cost,p.price]))}>Exportar</Button><Button icon={I.Plus} onClick={()=>productForm()}>Nuevo producto</Button></PageTitle><div className="inventory-layout"><div><div className="stats-grid compact"><Stat label="Productos" value={data.products.length} note="En el catálogo" icon={I.Box} color="green"/><Stat label="Stock bajo" value={data.products.filter(x=>stock(x,warehouse)>0&&stock(x,warehouse)<=x.min).length} note="Requieren atención" icon={I.AlertTriangle} color="orange"/><Stat label="Sin stock" value={data.products.filter(x=>stock(x,warehouse)===0).length} note="En este depósito" icon={I.X} color="red"/><Stat label="Valor del inventario" value={money(data.products.reduce((a,p)=>a+stock(p,warehouse)*p.cost,0))} note="Valorizado al costo" icon={I.Receipt}/></div><div className="filter-bar"><Search value={q} onChange={setQ} placeholder="Buscar por nombre, SKU o código de barras…"/><Field label="Categoría"><select value={category} onChange={e=>setCategory(e.target.value)}><option>Todas</option>{categories.map(c=><option key={c}>{c}</option>)}</select></Field><Field label="Estado"><select value={filter} onChange={e=>setFilter(e.target.value)}>{['Todos','Disponible','Stock bajo','Sin stock'].map(x=><option key={x}>{x}</option>)}</select></Field></div><Panel><Table headers={['Código','Producto','Stock','Mínimo','Precio de venta','Estado','']} empty={!rows.length}>{rows.map(x=><tr key={x.id} className={cn('clickable',x.id===p.id&&'row-selected')} onClick={()=>setSelected(x.id)}><td className="muted">{x.code}</td><td><button className="product-button" onClick={()=>setSelected(x.id)}><ProductName p={x}/></button></td><td><b>{num(stock(x,warehouse))}</b><small className="block">{x.unit}</small></td><td>{num(x.min)}</td><td className="nowrap">{money(x.price)}</td><td><Badge>{status(x,warehouse)}</Badge></td><td><IconButton icon={I.Edit} label={'Editar '+x.name} onClick={e=>{e.stopPropagation();productForm(x);}}/></td></tr>)}</Table><div className="pagination"><small>Mostrando {filtered.length?((page-1)*7+1):0}–{Math.min(page*7,filtered.length)} de {filtered.length} productos</small><div><IconButton icon={I.ArrowLeft} label="Página anterior" disabled={page===1} onClick={()=>setPage(page-1)}/><b>{page}</b><IconButton icon={I.ChevronRight} label="Página siguiente" disabled={page*7>=filtered.length} onClick={()=>setPage(page+1)}/></div></div></Panel></div><aside className="product-detail"><Button variant="secondary" icon={I.ArrowsExchange} onClick={()=>movementForm(p)}>Registrar movimiento</Button><Panel><div className="detail-hero"><ProductImage product={p} large/><h2>{p.name}</h2><p>Código: {p.code}</p><span>{p.brand}</span></div><div className="stock-pair"><div><small>Stock actual</small><strong>{num(stock(p,warehouse))}</strong><span>{p.unit}</span></div><div><small>Stock mínimo</small><strong>{p.min}</strong><span>{p.unit}</span></div></div><Badge>{status(p,warehouse)}</Badge><dl><div><dt>Categoría</dt><dd>{p.category}</dd></div><div><dt>Depósito</dt><dd>{warehouse}</dd></div><div><dt>Precio de venta</dt><dd>{money(p.price)}</dd></div></dl><div className="detail-subtitle"><b>Movimientos recientes</b><Button variant="text" onClick={()=>go('movimientos')}>Ver todos</Button></div>{data.movements.filter(x=>x.productId===p.id).slice(0,2).map(m=><div className="recent-move" key={m.id}><span className={'soft-icon '+(m.qty>0?'green':'red')}>{m.qty>0?<I.ArrowUp size={18}/>:<I.ArrowDown size={18}/>}</span><div><b>{m.type}</b><small>{date(m.date)}</small></div><strong className={m.qty>0?'success-text':'danger-text'}>{m.qty>0?'+':''}{num(m.qty)}</strong></div>)}{!data.movements.some(x=>x.productId===p.id)&&<p className="muted">Aún no hay movimientos para este producto.</p>}<Button variant="outline full" icon={I.Edit} onClick={()=>productForm(p)}>Editar producto</Button></Panel></aside></div></>}
function Movements(){const{data,warehouse,movementForm}=useApp();const[q,setQ]=useState(''),[type,setType]=useState('Todos');const rows=data.movements.filter(m=>{const p=data.products.find(x=>x.id===m.productId);return m.warehouse===warehouse&&(type==='Todos'||(type==='Entradas'?m.qty>0:m.qty<0))&&(p.name+' '+m.reason+' '+p.code).toLowerCase().includes(q.toLowerCase());});return <><PageTitle title="Movimientos de stock" subtitle="Cada entrada, salida y transferencia, en un solo historial."><Button icon={I.ArrowsExchange} onClick={()=>movementForm()}>Registrar movimiento</Button></PageTitle><MiniStats items={[["Movimientos",rows.length,I.ArrowsExchange,'blue'],['Entradas',rows.filter(x=>x.qty>0).length,I.ArrowUp,'green'],['Salidas',rows.filter(x=>x.qty<0).length,I.ArrowDown,'orange']]}/><div className="filter-bar"><Search value={q} onChange={setQ} placeholder="Buscar producto o referencia…"/><Field label="Tipo"><select value={type} onChange={e=>setType(e.target.value)}>{['Todos','Entradas','Salidas'].map(x=><option key={x}>{x}</option>)}</select></Field><Button variant="secondary" icon={I.Download} onClick={()=>csv('movimientos.csv',['Fecha','Producto','Tipo','Cantidad','Depósito','Referencia','Usuario'],rows.map(m=>[m.date,data.products.find(x=>x.id===m.productId).name,m.type,m.qty,m.warehouse,m.reason,m.user]))}>Exportar</Button></div><Panel><Table headers={['Fecha','Producto','Tipo','Cantidad','Depósito','Referencia','Responsable']} empty={!rows.length}>{rows.map(m=><tr key={m.id}><td>{date(m.date)}</td><td><ProductName p={data.products.find(x=>x.id===m.productId)}/></td><td><Badge>{m.type}</Badge></td><td className={m.qty>0?'success-text':'danger-text'}><b>{m.qty>0?'+':''}{num(m.qty)}</b></td><td>{m.warehouse}</td><td>{m.reason}</td><td>{m.user}</td></tr>)}</Table></Panel></>}
function Sales(){const{data,warehouse,openSale,viewInvoice,pay}=useApp();const[q,setQ]=useState(''),[filter,setFilter]=useState('Todas');const rows=data.invoices.filter(x=>x.warehouse===warehouse&&(x.number+' '+data.clients.find(c=>c.id===x.client)?.name).toLowerCase().includes(q.toLowerCase())&&(filter==='Todas'||(filter==='Pendientes'?x.total>x.paid&&x.state!=='Anulada':x.state===filter)));return <><PageTitle title="Ventas y facturación" subtitle="Tus comprobantes, cobros y cuentas pendientes."><Button icon={I.Plus} variant="green" onClick={openSale}>Nueva venta</Button></PageTitle><MiniStats items={[["Ventas registradas",data.invoices.filter(x=>x.state!=='Anulada').length,I.Receipt,'blue'],['Total vendido',money(data.invoices.filter(x=>x.state!=='Anulada').reduce((a,x)=>a+x.total,0)),I.ChartBar,'green'],['Saldo por cobrar',money(data.invoices.filter(x=>x.state!=='Anulada').reduce((a,x)=>a+x.total-x.paid,0)),I.Clock,'orange']]}/><div className="filter-bar"><Search value={q} onChange={setQ} placeholder="Buscar comprobante o cliente…"/><Field label="Estado"><select value={filter} onChange={e=>setFilter(e.target.value)}>{['Todas','Pendientes','Pagada','Parcial','Anulada'].map(x=><option key={x}>{x}</option>)}</select></Field><Button variant="secondary" icon={I.Download} onClick={()=>csv('ventas.csv',['Comprobante','Fecha','Cliente','Total','Cobrado','Estado'],rows.map(x=>[x.number,x.date,data.clients.find(c=>c.id===x.client)?.name,x.total,x.paid,x.state]))}>Exportar</Button></div><Panel><Table headers={['Comprobante','Fecha','Cliente','Forma de pago','Total','Saldo','Estado','Acciones']} empty={!rows.length}>{rows.map(x=><tr key={x.id}><td><button className="table-link" onClick={()=>viewInvoice(x)}>{x.number}</button></td><td>{date(x.date)}</td><td>{data.clients.find(c=>c.id===x.client)?.name}</td><td>{x.payment}</td><td className="nowrap"><b>{money(x.total)}</b></td><td className="nowrap">{x.state==='Anulada'?'—':money(x.total-x.paid)}</td><td><Badge>{x.state}</Badge></td><td><div className="row-actions"><IconButton icon={I.Eye} label={'Ver comprobante '+x.number} onClick={()=>viewInvoice(x)}/>{x.total>x.paid&&x.state!=='Anulada'&&<Button variant="outline small" onClick={()=>pay(x)}>Cobrar</Button>}</div></td></tr>)}</Table></Panel></>}
function SaleEditor(){const{data,user,warehouse,cart,setCart,saleClient,setSaleClient,saleDiscount,go,commit,notify,viewInvoice}=useApp();const[q,setQ]=useState(''),[payment,setPayment]=useState('Efectivo'),[discount,setDiscount]=useState(saleDiscount||0),[received,setReceived]=useState(''),[error,setError]=useState('');const items=cart.map(x=>({...x,p:data.products.find(p=>p.id===x.productId)})),subtotal=items.reduce((a,x)=>a+x.qty*x.p.price,0),total=Math.max(0,Math.round(subtotal-Number(discount))),matches=data.products.filter(p=>(p.name+' '+p.code+' '+p.barcode).toLowerCase().includes(q.toLowerCase()));function add(p){setError('');if(stock(p,warehouse)<=0){setError('Este producto no tiene stock en '+warehouse+'.');return;}const existing=cart.find(x=>x.productId===p.id),qty=(existing?.qty||0)+1;if(qty>stock(p,warehouse)){setError('No hay más stock disponible para '+p.name+'.');return;}setCart(existing?cart.map(x=>x.productId===p.id?{...x,qty}:x):[...cart,{productId:p.id,qty:1}]);setQ('');}function saveQuote(){if(!cart.length){setError('Agregá productos antes de guardar.');return;}const s=structuredClone(data);s.quotes.unshift({id:uid(),number:'PRE-'+String(s.quotes.length+1).padStart(5,'0'),date:TODAY,client:saleClient,warehouse,items:cart.map(x=>({...x})),discount:Number(discount)||0,total,state:'Borrador'});commit(s,'Presupuesto guardado');setCart([]);go('presupuestos');}function finish(){setError('');try{const result=checkout(data,{items:cart,client:saleClient,warehouse,discount,received,payment},user.name);commit(result.state,'Venta registrada. Stock actualizado.');setCart([]);viewInvoice(result.invoice);}catch(e){setError(e.message);}}
return <><PageTitle title="Nueva venta" subtitle="Registrá la venta y actualizá el stock en un solo paso."><Button variant="secondary" icon={I.ArrowLeft} onClick={()=>go('ventas')}>Volver a ventas</Button></PageTitle><div className="pos-layout"><Panel className="pos-products"><div className="pos-fields"><Field label="Cliente"><select value={saleClient} onChange={e=>setSaleClient(e.target.value)}>{data.clients.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Condición de venta"><select value={payment==='Crédito'?'Crédito':'Contado'} onChange={e=>setPayment(e.target.value==='Crédito'?'Crédito':'Efectivo')}><option>Contado</option><option>Crédito</option></select></Field><Field label="Depósito"><input readOnly value={warehouse}/></Field></div><form className="pos-search" onSubmit={e=>{e.preventDefault();if(matches[0])add(matches[0]);}}><I.Barcode size={26}/><input aria-label="Buscar producto para la venta" placeholder="Buscar producto o escanear código…" value={q} onChange={e=>setQ(e.target.value)}/><Button type="submit" icon={I.Search} aria-label="Agregar primer resultado"/></form>{q?<div className="product-results">{matches.slice(0,6).map(p=><button key={p.id} onClick={()=>add(p)}><ProductName p={p}/><span>{money(p.price)}<small>{num(stock(p,warehouse))} {p.unit} disponibles</small></span><I.Plus size={18}/></button>)}{!matches.length&&<Empty/>}</div>:<div className="recommended"><b>Productos frecuentes</b><div>{[data.products[0],data.products[2],data.products[1]].map(p=><button key={p.id} onClick={()=>add(p)} aria-label={'Agregar '+p.name}><ProductImage product={p}/><span>{p.name}<small>{money(p.price)}</small></span><I.Plus size={20}/></button>)}</div></div>}<Table headers={['','Producto','Cantidad','Precio','Importe','Stock']} empty={!cart.length}>{items.map(({p,qty,productId})=><tr key={productId}><td><IconButton icon={I.X} label={'Quitar '+p.name} onClick={()=>setCart(cart.filter(x=>x.productId!==productId))}/></td><td><ProductName p={p}/></td><td><div className="quantity"><button aria-label={'Restar '+p.name} onClick={()=>setCart(cart.map(x=>x.productId===productId?{...x,qty:Math.max(1,x.qty-1)}:x))}><I.Minus size={13}/></button><input aria-label={'Cantidad '+p.name} type="number" min={['metro','kilo'].includes(p.unit)?0.01:1} step={['metro','kilo'].includes(p.unit)?0.01:1} value={qty} onChange={e=>setCart(cart.map(x=>x.productId===productId?{...x,qty:Number(e.target.value)}:x))}/><button aria-label={'Sumar '+p.name} onClick={()=>setCart(cart.map(x=>x.productId===productId?{...x,qty:x.qty+1}:x))}><I.Plus size={13}/></button></div><small className="block">{p.unit}</small></td><td className="nowrap">{money(p.price)}</td><td className="nowrap"><b>{money(qty*p.price)}</b></td><td><span className="stock-note">{num(stock(p,warehouse))} disp.</span></td></tr>)}</Table><div className="pos-bottom"><I.InfoCircle size={17}/><span>Los precios son de ejemplo. El stock se descuenta al confirmar la venta.</span></div></Panel><Panel className="checkout"><h2><I.ShoppingCart size={24}/> Resumen de venta</h2><dl><div><dt>Subtotal</dt><dd>{money(subtotal)}</dd></div><div><dt><label htmlFor="discount">Descuento (Gs.)</label></dt><dd><input id="discount" type="number" min="0" max={subtotal} value={discount} onChange={e=>setDiscount(e.target.value)}/></dd></div></dl><div className="total"><span>Total</span><strong>{money(total)}</strong></div><h3>Forma de pago</h3>{payment==='Crédito'?<div className="credit-note"><I.Clock size={22}/><span>Venta a crédito<small>Se registrará en la cuenta del cliente.</small></span></div>:<div className="payment-options">{[['Efectivo',I.Cash],['Tarjeta',I.CreditCard],['Transferencia',I.BuildingBank]].map(([name,Icon])=><button key={name} className={payment===name?'active':''} onClick={()=>setPayment(name)}><Icon size={21}/>{name}</button>)}</div>}{payment==='Efectivo'&&<><Field label="Monto recibido (Gs.)" type="number" min="0" value={received} onChange={e=>setReceived(e.target.value)} placeholder="0"/><div className="change"><span>Vuelto</span><strong>{money(Math.max(0,Number(received)-total))}</strong></div></>}{payment==='Crédito'&&<p className="muted">Límite del cliente: {money(data.clients.find(c=>c.id===saleClient)?.credit)}</p>}{error&&<div className="error" role="alert">{error}</div>}<Button variant="green full" icon={I.Receipt} disabled={!cart.length} onClick={finish}>{payment==='Crédito'?'Emitir a crédito':'Cobrar y emitir comprobante'}</Button><Button variant="secondary full" icon={I.FileText} disabled={!cart.length} onClick={saveQuote}>Guardar presupuesto</Button></Panel></div></>}
function InvoiceModal({id}){const{data,user,setModal,pay,confirm,act}=useApp();const inv=data.invoices.find(x=>x.id===id),client=data.clients.find(c=>c.id===inv.client);return <Modal title="Comprobante de venta" onClose={()=>setModal(null)} wide className="receipt-modal"><div className="receipt print-area"><div className="receipt-head"><div><Brand dark/><h3>{data.settings.company}</h3><p>{data.settings.doc}<br/>{data.settings.address}<br/>{data.settings.phone}</p></div><div><span className="demo-receipt">COMPROBANTE DEMOSTRATIVO</span><h2>{inv.number}</h2><p>{date(inv.date)} · {inv.warehouse}</p><Badge>{inv.state}</Badge></div></div><div className="receipt-client"><b>Cliente: {client.name}</b><span>RUC / documento: {client.doc}</span><span>Forma de pago: {inv.payment}</span></div><Table headers={['Descripción','Cantidad','Precio','Importe']}>{inv.items.map(x=><tr key={x.productId}><td>{x.name}</td><td>{num(x.qty)} {x.unit}</td><td>{money(x.price)}</td><td>{money(x.qty*x.price)}</td></tr>)}</Table><div className="receipt-totals"><span>Descuento <b>{money(inv.discount)}</b></span><strong>Total <b>{money(inv.total)}</b></strong><span>Cobrado <b>{money(inv.paid)}</b></span><span>Saldo pendiente <b>{inv.state==='Anulada'?'—':money(inv.total-inv.paid)}</b></span></div><p className="receipt-note">Documento de muestra sin validez fiscal.</p></div><div className="modal-actions wrap"><Button variant="secondary" icon={I.Printer} onClick={()=>window.print()}>Imprimir / PDF</Button>{inv.state!=='Anulada'&&inv.total>inv.paid&&<Button icon={I.Cash} onClick={()=>pay(inv)}>Registrar cobro</Button>}{inv.state!=='Anulada'&&user.role!=='Depósito'&&<Button variant="danger-outline" icon={I.ArrowBackUp} onClick={()=>confirm('Anular venta','Se devolverán los productos al stock y se registrará el reintegro de lo cobrado en la caja de demostración.',()=>{if(!act(s=>voidInvoice(s,id,user.name),'Venta anulada y stock devuelto'))throw Error('No se pudo anular. Revisá el estado de la caja.');})}>Anular venta</Button>}</div></Modal>}
function Purchases(){const{data,warehouse,setModal,act,user}=useApp();const[q,setQ]=useState('');const rows=data.purchases.filter(x=>x.warehouse===warehouse&&(x.number+' '+data.suppliers.find(s=>s.id===x.supplier)?.name).toLowerCase().includes(q.toLowerCase()));return <><PageTitle title="Compras" subtitle="Planificá la reposición y recibí mercadería en tu depósito."><Button icon={I.Plus} onClick={()=>setModal({kind:'purchase'})}>Nueva orden de compra</Button></PageTitle><MiniStats items={[["Órdenes pendientes",rows.filter(x=>x.state==='Pendiente').length,I.Clock,'orange'],['Compras recibidas',rows.filter(x=>x.state==='Recibida').length,I.Truck,'green'],['Total en órdenes',money(rows.reduce((a,x)=>a+x.total,0)),I.ShoppingCart,'blue']]}/><div className="filter-bar"><Search value={q} onChange={setQ} placeholder="Buscar orden o proveedor…"/></div><Panel><Table headers={['Orden','Fecha','Proveedor','Depósito','Total','Estado','Acciones']} empty={!rows.length}>{rows.map(x=><tr key={x.id}><td><button className="table-link" onClick={()=>setModal({kind:'purchase-detail',id:x.id})}>{x.number}</button></td><td>{date(x.date)}</td><td>{data.suppliers.find(s=>s.id===x.supplier)?.name}</td><td>{x.warehouse}</td><td><b>{money(x.total)}</b></td><td><Badge>{x.state}</Badge></td><td>{x.state==='Pendiente'?<Button variant="outline small" icon={I.Truck} onClick={()=>act(s=>receivePurchase(s,x.id,user.name),'Compra recibida. Stock actualizado.')}>Recibir mercadería</Button>:<Button variant="text" onClick={()=>setModal({kind:'purchase-detail',id:x.id})}>Ver detalle</Button>}</td></tr>)}</Table></Panel><div className="info-strip"><I.InfoCircle size={19}/> El stock se actualiza al recibir la mercadería, no al crear la orden de compra.</div></>}
function PurchaseModal(){const{data,warehouse,commit,setModal}=useApp();const[supplier,setSupplier]=useState(data.suppliers[0].id),[depot,setDepot]=useState(warehouse),[productId,setProductId]=useState(data.products[0].id),[qty,setQty]=useState(1),[items,setItems]=useState([]),[error,setError]=useState('');const total=items.reduce((a,x)=>a+x.qty*x.cost,0);function add(){try{const p=data.products.find(x=>x.id===Number(productId));validQty(p,Number(qty));if(items.some(x=>x.productId===p.id))throw Error('El producto ya está en la orden. Quitalo para modificar la cantidad.');setItems([...items,{productId:p.id,name:p.name,qty:Number(qty),cost:p.cost}]);setError('');}catch(e){setError(e.message);}}return <Modal title="Nueva orden de compra" onClose={()=>setModal(null)} wide><div className="form-grid"><Field label="Proveedor"><select value={supplier} onChange={e=>setSupplier(e.target.value)}>{data.suppliers.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Depósito de recepción"><select value={depot} onChange={e=>setDepot(e.target.value)}>{warehouses.map(x=><option key={x}>{x}</option>)}</select></Field></div><div className="purchase-add"><Field label="Producto"><select value={productId} onChange={e=>setProductId(e.target.value)}>{data.products.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Cantidad" type="number" min="0.01" value={qty} onChange={e=>setQty(e.target.value)}/><Button icon={I.Plus} onClick={add}>Agregar</Button></div><Table headers={['Producto','Cantidad','Costo','Importe','']} empty={!items.length}>{items.map(x=><tr key={x.productId}><td>{x.name}</td><td>{num(x.qty)}</td><td>{money(x.cost)}</td><td>{money(x.qty*x.cost)}</td><td><IconButton icon={I.X} label={'Quitar '+x.name} onClick={()=>setItems(items.filter(i=>i.productId!==x.productId))}/></td></tr>)}</Table><div className="total"><span>Total de la orden</span><strong>{money(total)}</strong></div>{error&&<div className="error" role="alert">{error}</div>}<div className="modal-actions"><Button variant="secondary" onClick={()=>setModal(null)}>Cancelar</Button><Button disabled={!items.length} onClick={()=>{const s=structuredClone(data);s.purchases.unshift({id:uid(),number:'OC-'+String(129+s.purchases.length-2).padStart(5,'0'),date:TODAY,supplier,warehouse:depot,items,total,state:'Pendiente'});commit(s,'Orden de compra creada');setModal(null);}}>Crear orden</Button></div></Modal>}
function PurchaseDetail({id}){const{data,setModal,act,user}=useApp();const p=data.purchases.find(x=>x.id===id);return <Modal title={'Orden '+p.number} onClose={()=>setModal(null)} wide><p>{data.suppliers.find(x=>x.id===p.supplier)?.name} · {p.warehouse} · {date(p.date)}</p><Badge>{p.state}</Badge><Table headers={['Producto','Cantidad','Costo unitario','Importe']}>{p.items.map(x=><tr key={x.productId}><td>{x.name}</td><td>{num(x.qty)}</td><td>{money(x.cost)}</td><td>{money(x.qty*x.cost)}</td></tr>)}</Table><div className="total"><span>Total</span><strong>{money(p.total)}</strong></div><div className="modal-actions">{p.state==='Pendiente'&&<Button icon={I.Truck} onClick={()=>{if(act(s=>receivePurchase(s,p.id,user.name),'Compra recibida. Stock actualizado.'))setModal(null);}}>Recibir mercadería</Button>}</div></Modal>}
function Quotes(){const{data,setCart,setSaleClient,setSaleDiscount,setWarehouse,go,openSale,confirm,commit}=useApp();return <><PageTitle title="Presupuestos" subtitle="Prepará una propuesta y convertíla en venta cuando tu cliente confirme."><Button icon={I.Plus} onClick={openSale}>Nuevo presupuesto</Button></PageTitle><Panel><Table headers={['Número','Fecha','Cliente','Productos','Total','Estado','Acciones']} empty={!data.quotes.length}>{data.quotes.map(q=><tr key={q.id}><td><b>{q.number}</b></td><td>{date(q.date)}</td><td>{data.clients.find(c=>c.id===q.client)?.name}</td><td>{q.items.length}</td><td>{money(q.total)}</td><td><Badge>{q.state}</Badge></td><td><div className="row-actions"><Button variant="outline small" onClick={()=>{setCart(q.items.map(x=>({...x})));setSaleClient(q.client);setSaleDiscount(q.discount);setWarehouse(q.warehouse);go('nueva-venta');}}>Convertir en venta</Button><IconButton icon={I.Trash} label={'Eliminar '+q.number} onClick={()=>confirm('Eliminar presupuesto','Se quitará este presupuesto de la maqueta.',()=>{const s=structuredClone(data);s.quotes=s.quotes.filter(x=>x.id!==q.id);commit(s,'Presupuesto eliminado');})}/></div></td></tr>)}</Table></Panel><div className="info-strip"><I.InfoCircle size={19}/> Un presupuesto no reserva ni descuenta stock. Las cantidades se validan al confirmar la venta.</div></>}
function Contacts({type}){const{data,contactForm,setModal}=useApp();const[q,setQ]=useState(''),clients=type==='clientes',rows=data[clients?'clients':'suppliers'].filter(c=>(c.name+' '+c.doc+' '+c.phone).toLowerCase().includes(q.toLowerCase()));const debt=id=>data.invoices.filter(x=>x.client===id&&x.state!=='Anulada').reduce((a,x)=>a+x.total-x.paid,0);return <><PageTitle title={clients?'Clientes':'Proveedores'} subtitle={clients?'Tus contactos, límites de crédito y cuentas corrientes.':'Toda la información de quienes abastecen tu ferretería.'}><Button icon={I.Plus} onClick={()=>contactForm(type)}>Nuevo {clients?'cliente':'proveedor'}</Button></PageTitle><div className="filter-bar"><Search value={q} onChange={setQ} placeholder="Buscar por nombre, documento o teléfono…"/><Button variant="secondary" icon={I.Download} onClick={()=>csv(type+'.csv',['Nombre','Documento','Teléfono','Correo','Dirección'],rows.map(x=>[x.name,x.doc,x.phone,x.email,x.address]))}>Exportar</Button></div><Panel><Table headers={['Nombre / razón social','Documento','Contacto',clients?'Límite de crédito':'Dirección',...(clients?['Saldo pendiente']:[]),'Acciones']} empty={!rows.length}>{rows.map(c=><tr key={c.id}><td><div className="contact-name"><span className="contact-avatar">{c.name[0]}</span><b>{c.name}</b></div></td><td>{c.doc}</td><td>{c.phone||'—'}<small className="block">{c.email}</small></td><td>{clients?money(c.credit):c.address}</td>{clients&&<td className={debt(c.id)>0?'danger-text':''}>{money(debt(c.id))}</td>}<td><div className="row-actions">{clients&&<Button variant="text" onClick={()=>setModal({kind:'statement',id:c.id})}>Cuenta corriente</Button>}{c.id!=='c1'&&<IconButton icon={I.Edit} label={'Editar '+c.name} onClick={()=>contactForm(type,c)}/>}</div></td></tr>)}</Table></Panel></>}
function Statement({id}){const{data,setModal,pay}=useApp();const c=data.clients.find(x=>x.id===id),rows=data.invoices.filter(x=>x.client===id&&x.state!=='Anulada');return <Modal title={'Cuenta corriente · '+c.name} onClose={()=>setModal(null)} wide><MiniStats items={[["Límite de crédito",money(c.credit),I.ShieldCheck,'blue'],['Saldo pendiente',money(rows.reduce((a,x)=>a+x.total-x.paid,0)),I.Clock,'orange']]}/><Table headers={['Comprobante','Fecha','Total','Cobrado','Saldo','']} empty={!rows.length}>{rows.map(x=><tr key={x.id}><td>{x.number}</td><td>{date(x.date)}</td><td>{money(x.total)}</td><td>{money(x.paid)}</td><td>{money(x.total-x.paid)}</td><td>{x.total>x.paid&&<Button variant="outline small" onClick={()=>pay(x)}>Cobrar</Button>}</td></tr>)}</Table></Modal>}
function Cash(){const{data,commit,form,confirm}=useApp(),cash=data.cash,expected=cashExpected(cash);function open(){form('Abrir caja',[{name:'amount',label:'Fondo inicial en efectivo (Gs.)',type:'number',min:0}],{amount:0},v=>{const s=structuredClone(data);s.cash={...s.cash,open:true,opening:Number(v.amount),entries:[],openedAt:TODAY};commit(s,'Caja abierta');});}function entry(){form('Registrar movimiento de caja',[{name:'type',label:'Tipo',options:['Ingreso','Egreso']},{name:'amount',label:'Importe (Gs.)',type:'number',min:1},{name:'method',label:'Forma de pago',options:['Efectivo','Transferencia','Tarjeta']},{name:'reason',label:'Concepto'}],{type:'Egreso',method:'Efectivo',amount:'',reason:''},v=>{if(v.type==='Egreso'&&v.method==='Efectivo'&&Number(v.amount)>expected)throw Error('El egreso supera el efectivo disponible.');const s=structuredClone(data);s.cash.entries.unshift({...v,amount:Number(v.amount),id:uid(),date:TODAY});commit(s,'Movimiento de caja registrado');});}function close(){form('Cerrar caja',[{name:'counted',label:'Efectivo contado (Gs.)',type:'number',min:0}],{counted:expected},v=>{const s=structuredClone(data);s.cash.history.unshift({id:uid(),date:TODAY,opening:cash.opening,expected,counted:Number(v.counted),difference:Number(v.counted)-expected});s.cash.open=false;commit(s,'Caja cerrada. Arqueo guardado.');},'Efectivo esperado: '+money(expected)+'. Se guardará cualquier diferencia de arqueo.','Confirmar cierre');}return <><PageTitle title="Caja" subtitle="Seguí tus cobros, gastos y el efectivo disponible.">{cash.open?<><Button variant="secondary" icon={I.Plus} onClick={entry}>Movimiento de caja</Button><Button icon={I.Lock} onClick={close}>Cerrar caja</Button></>:<Button icon={I.Plus} variant="green" onClick={open}>Abrir caja</Button>}</PageTitle><div className="cash-status"><Badge>{cash.open?'Activa':'Inactiva'}</Badge><span>{cash.open?'Caja abierta · '+date(cash.openedAt):'Caja cerrada · Abrila para registrar cobros.'}</span></div><MiniStats items={[["Fondo inicial",money(cash.opening),I.Wallet,'blue'],['Ingresos',money(cash.entries.filter(e=>e.type==='Ingreso').reduce((a,x)=>a+x.amount,0)),I.ArrowUp,'green'],['Egresos',money(cash.entries.filter(e=>e.type==='Egreso').reduce((a,x)=>a+x.amount,0)),I.ArrowDown,'red'],['Efectivo esperado',money(expected),I.Cash,'purple']]}/><Panel title="Movimientos del turno" action={<Button variant="text" icon={I.Download} onClick={()=>csv('caja.csv',['Fecha','Tipo','Concepto','Medio','Importe'],cash.entries.map(x=>[x.date,x.type,x.reason,x.method,x.amount]))}>Exportar</Button>}><Table headers={['Fecha','Concepto','Tipo','Medio de pago','Importe']} empty={!cash.entries.length}>{cash.entries.map(x=><tr key={x.id}><td>{date(x.date)}</td><td>{x.reason}</td><td><Badge>{x.type}</Badge></td><td>{x.method}</td><td className={x.type==='Ingreso'?'success-text':'danger-text'}><b>{x.type==='Ingreso'?'+':'−'} {money(x.amount)}</b></td></tr>)}</Table></Panel>{cash.history.length>0&&<Panel title="Historial de cierres" className="mt"><Table headers={['Fecha','Fondo inicial','Esperado','Contado','Diferencia']}>{cash.history.map(x=><tr key={x.id}><td>{date(x.date)}</td><td>{money(x.opening)}</td><td>{money(x.expected)}</td><td>{money(x.counted)}</td><td>{money(x.difference)}</td></tr>)}</Table></Panel>}</>}
function Reports(){const{data,warehouse}=useApp();const[from,setFrom]=useState('2026-10-01'),[to,setTo]=useState(TODAY),[tab,setTab]=useState('Ventas');const invoices=data.invoices.filter(x=>x.state!=='Anulada'&&x.date>=from&&x.date<=to&&x.warehouse===warehouse),total=invoices.reduce((a,x)=>a+x.total,0),cost=invoices.reduce((a,x)=>a+x.items.reduce((t,i)=>t+i.cost*i.qty,0),0);const top=data.products.map(p=>{const items=invoices.flatMap(x=>x.items).filter(i=>i.productId===p.id);return{...p,qty:items.reduce((a,i)=>a+i.qty,0),total:items.reduce((a,i)=>a+i.qty*i.price,0)};}).filter(p=>p.qty>0).sort((a,b)=>b.total-a.total);return <><PageTitle title="Reportes" subtitle="Información clara para tomar mejores decisiones."><Button variant="secondary" icon={I.Printer} onClick={()=>window.print()}>Imprimir</Button><Button icon={I.Download} onClick={()=>{if(tab==='Inventario')csv('reporte-inventario.csv',['Código','Producto','Stock','Costo','Valorización'],data.products.map(p=>[p.code,p.name,stock(p,warehouse),p.cost,stock(p,warehouse)*p.cost]));else csv('reporte-ventas.csv',['Fecha','Comprobante','Total','Cobrado'],invoices.map(x=>[x.date,x.number,x.total,x.paid]));}}>Exportar CSV</Button></PageTitle><div className="report-filters"><Field label="Desde" type="date" value={from} max={to} onChange={e=>setFrom(e.target.value)}/><Field label="Hasta" type="date" value={to} min={from} max={TODAY} onChange={e=>setTo(e.target.value)}/><div><I.Calendar size={19}/><span>{warehouse}<small>Período: {date(from||TODAY)} al {date(to||TODAY)}</small></span></div></div><div className="tabs">{['Ventas','Inventario','Cuentas por cobrar'].map(x=><button key={x} className={tab===x?'active':''} onClick={()=>setTab(x)}>{x}</button>)}</div>{tab==='Ventas'?<><MiniStats items={[["Ventas del período",money(total),I.Receipt,'blue'],['Margen bruto estimado',money(total-cost),I.ChartBar,'green'],['Ticket promedio',money(invoices.length?total/invoices.length:0),I.ShoppingCart,'purple'],['Operaciones',invoices.length,I.FileText,'orange']]}/><div className="dashboard-bottom"><Panel title="Ventas por día · última semana" icon={I.ChartBar}><SalesChart invoices={invoices}/></Panel><Panel title="Productos más vendidos" icon={I.Package}><Table headers={['Producto','Cantidad','Venta bruta']} empty={!top.length}>{top.slice(0,5).map(p=><tr key={p.id}><td>{p.name}</td><td>{num(p.qty)} {p.unit}</td><td><b>{money(p.total)}</b></td></tr>)}</Table></Panel></div><p className="muted">Margen estimado = ventas menos costo registrado de los productos. No incluye gastos operativos.</p></>:tab==='Inventario'?<Panel title="Valorización actual por categoría" icon={I.Box}><Composition products={data.products} warehouse={warehouse}/><Table headers={['Categoría','Productos','Valor al costo']}>{categories.map(c=><tr key={c}><td>{c}</td><td>{data.products.filter(p=>p.category===c).length}</td><td>{money(data.products.filter(p=>p.category===c).reduce((a,p)=>a+stock(p,warehouse)*p.cost,0))}</td></tr>)}</Table><p className="muted">El inventario muestra el saldo actual; no es un cierre histórico del período seleccionado.</p></Panel>:<Panel title="Cuentas por cobrar del período"><Table headers={['Cliente','Comprobantes pendientes','Saldo']} empty={!invoices.some(x=>x.total>x.paid)}>{data.clients.map(c=>{const list=invoices.filter(x=>x.client===c.id&&x.total>x.paid);return list.length>0&&<tr key={c.id}><td>{c.name}</td><td>{list.length}</td><td>{money(list.reduce((a,x)=>a+x.total-x.paid,0))}</td></tr>;})}</Table></Panel>}</>}
function Users(){
  const {form,notify}=useApp();
  const [directory,setDirectory]=useState({users:[],people:[],profiles:[]});
  const [loading,setLoading]=useState(true),[error,setError]=useState(''),[revision,setRevision]=useState(0);
  useEffect(()=>{let active=true;setLoading(true);setError('');loadUserDirectory().then(result=>{if(active)setDirectory(result);}).catch(e=>{if(active)setError(e.message);}).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},[revision]);
  const available=directory.people.filter(p=>p.activo&&!directory.users.some(u=>u.personId===p.id));
  const profiles=directory.profiles.filter(p=>p.activo);
  function add(){form('Nuevo usuario',[
    {name:'personaId',label:'Persona',options:available.map(p=>({value:p.id,label:p.nombres+' '+p.apellidos}))},
    {name:'username',label:'Nombre de usuario'},
    {name:'perfilId',label:'Perfil',options:profiles.map(p=>({value:p.id,label:p.nombre}))},
    {name:'password',label:'Contraseña inicial',type:'password',minLength:12}
  ],{personaId:available[0]?.id,perfilId:profiles[0]?.id},async values=>{
    const created=await createUser(values),person=directory.people.find(p=>p.id===created.personaId),profile=directory.profiles.find(p=>p.id===created.perfilId);
    setDirectory(current=>({...current,users:[...current.users,{id:created.id,personId:created.personaId,username:created.nombreUsuario,name:person?person.nombres+' '+person.apellidos:created.nombreUsuario,role:profile?.nombre||'Sin perfil',active:created.activo}]}));
    notify('Usuario creado en NexaBack');
  },'Seleccioná una persona activa sin cuenta y un perfil activo ya registrados. La contraseña debe tener entre 12 y 128 caracteres.');}
  return <><PageTitle title="Usuarios y permisos" subtitle="Usuarios, personas y perfiles registrados en NexaBack."><Button variant="secondary" icon={I.Refresh} onClick={()=>setRevision(v=>v+1)} disabled={loading}>Actualizar</Button><Button icon={I.Plus} onClick={add} disabled={loading||!available.length||!profiles.length}>Nuevo usuario</Button></PageTitle>
    {loading?<Panel><p role="status">Cargando usuarios…</p></Panel>:error?<div className="error" role="alert">{error}</div>:<>
      <div className="role-cards">{directory.profiles.map(p=><Panel key={p.id}><span className="soft-icon blue"><I.ShieldCheck size={24}/></span><h3>{p.nombre}</h3><p>{p.descripcion||'Perfil registrado en el sistema.'}</p></Panel>)}</div>
      <Panel title="Equipo de trabajo"><Table headers={['Persona','Usuario','Perfil','Estado']} empty={!directory.users.length}>{directory.users.map(u=><tr key={u.id}><td><div className="contact-name"><span className="contact-avatar">{u.name[0]}</span><b>{u.name}</b></div></td><td>{u.username}</td><td>{u.role}</td><td><Badge>{u.active?'Activa':'Inactiva'}</Badge></td></tr>)}</Table></Panel>
      {(!available.length||!profiles.length)&&<p className="muted">Para crear una cuenta necesitás una persona activa sin usuario y un perfil activo, registrados previamente en el backend.</p>}
    </>}
  </>;
}
function Settings(){const{data,commit,confirm}=useApp();const[v,setV]=useState({...data.settings});return <><PageTitle title="Configuración" subtitle="La información y preferencias de tu ferretería."/><div className="settings-layout"><Panel title="Datos del negocio" icon={I.BuildingStore}><form onSubmit={e=>{e.preventDefault();if(!/^\d{3}-\d{3}$/.test(v.prefix))return;const s=structuredClone(data);s.settings=v;commit(s,'Configuración guardada');}}><div className="form-grid">{[['company','Nombre del negocio'],['doc','RUC / documento'],['address','Dirección'],['phone','Teléfono'],['email','Correo electrónico'],['prefix','Serie de comprobantes']].map(([key,label])=><Field key={key} label={label} type={key==='email'?'email':'text'} required value={v[key]} pattern={key==='prefix'?'[0-9]{3}-[0-9]{3}':undefined} title={key==='prefix'?'Formato: 001-001':undefined} onChange={e=>setV({...v,[key]:e.target.value})}/>)}</div><div className="modal-actions"><Button type="submit" icon={I.Check}>Guardar cambios</Button></div></form></Panel><Panel title="Acerca de esta maqueta" icon={I.InfoCircle}><p>Un espacio para probar el funcionamiento de tu ferretería con datos de ejemplo.</p><dl><div><dt>Moneda</dt><dd>Guaraníes (Gs.)</dd></div><div><dt>Depósitos</dt><dd>Casa central y Norte</dd></div><div><dt>Comprobantes</dt><dd>Demostrativos</dd></div></dl><p className="muted">Los cambios comerciales se guardan en este navegador. El login y los usuarios se consultan en NexaBack con PostgreSQL.</p><Button variant="danger-outline" icon={I.Refresh} onClick={()=>confirm('Restablecer datos de ejemplo','Se reemplazarán los productos, ventas y movimientos de esta maqueta por los datos iniciales. Esta acción no modifica ningún sistema real.',()=>{const s=seed();commit(s,'Datos de ejemplo restablecidos');setV(s.settings);})}>Restablecer demostración</Button></Panel></div><Panel title="Actividad reciente" className="mt"><Table headers={['Fecha','Usuario','Acción']} empty={!data.audit.length}>{data.audit.slice(0,12).map(x=><tr key={x.id}><td>{date(x.date)}</td><td>{x.user}</td><td>{x.action}</td></tr>)}</Table></Panel></>}








